content.text:
{
  "name": "MATLAB兼容HDF5文件导出器",
  "name_en": "MAT-Compatible HDF5 File Exporter",
  "manufacturer": "",
  "description": "用于创建和写入与 MATLAB 兼容的 HDF5 数据文件的软件组件，适合实验数据归档、批量保存及复数数据记录。",
  "description_en": "A software component for creating and writing MATLAB-compatible HDF5 data files, suitable for experiment data archiving, batch data saving, and recording complex-valued data.",
  "tag_hints": [
    "HDF5 data export",
    "MATLAB compatibility",
    "experiment data logging",
    "batch data writing",
    "complex-valued data",
    "data archiving"
  ],
  "actions": [
    {
      "action_name": "auto-batch_complex_write",
      "description": "批量写入多组复数数据到文件。",
      "description_en": "Write multiple sets of complex-valued data to the file in batch."
    },
    {
      "action_name": "auto-batch_write",
      "description": "批量写入多组数据到文件。",
      "description_en": "Write multiple datasets to the file in batch."
    },
    {
      "action_name": "auto-close_file",
      "description": "关闭当前数据文件。",
      "description_en": "Close the current data file."
    },
    {
      "action_name": "auto-create_complex_dataset",
      "description": "创建用于存储复数数据的数据集结构。",
      "description_en": "Create a dataset structure for storing complex-valued data."
    },
    {
      "action_name": "auto-create_dataset",
      "description": "创建指定名称和数据类型的数据集。",
      "description_en": "Create a dataset with the specified name and data type."
    },
    {
      "action_name": "auto-create_file",
      "description": "新建一个 MATLAB 兼容的 HDF5 数据文件。",
      "description_en": "Create a new MATLAB-compatible HDF5 data file."
    },
    {
      "action_name": "auto-create_group",
      "description": "在文件中创建数据分组。",
      "description_en": "Create a group in the file."
    },
    {
      "action_name": "auto-open_file",
      "description": "打开一个现有数据文件。",
      "description_en": "Open an existing data file."
    },
    {
      "action_name": "auto-reopen",
      "description": "重新打开当前数据文件。",
      "description_en": "Reopen the current data file."
    },
    {
      "action_name": "auto-write_complex_data",
      "description": "向复数数据集写入复数数据及对应时间信息。",
      "description_en": "Write complex-valued data and corresponding time information to a complex dataset."
    },
    {
      "action_name": "auto-write_data",
      "description": "向指定数据集写入数据。",
      "description_en": "Write data to the specified dataset."
    }
  ]
}

